 "parameters": [
  {
   "name": "project_id",
   "type": "integer",
   "required": true,
   "description": "The ID of the project. You can use 0 for your Inbox project.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from todoist app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "section_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the section to filter tasks by. Set it to 0 for tasks without a section.",
   "default": null,
   "constraints": []
  },
  {
   "name": "assignee_email",
   "type": "string",
   "required": false,
   "description": "Email address of the assignee to filter tasks by.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "assigner_email",
   "type": "string",
   "required": false,
   "description": "Email address of the assigner to filter tasks by.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "priority",
   "type": "string",
   "required": false,
   "description": "The priority to filter tasks by.",
   "default": null,
   "constraints": [
    "value in ['high', 'medium', 'low']"
   ]
  },
  {
   "name": "is_completed",
   "type": "boolean",
   "required": false,
